CREATE TABLE IF NOT EXISTS repositories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_id TEXT NOT NULL, name TEXT NOT NULL, url TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, ext_count INTEGER NOT NULL DEFAULT 0, index_data JSONB NOT NULL DEFAULT '[]'::jsonb, last_error TEXT, last_refreshed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (owner_id, url))